// Small slots of the single-name commands (generated by gen.pl).
#include "FunctionStr/Str.h"

Function *ShowPropFunction::Create(ArgList *list)
{
    ShowPropFunction *f = new ShowPropFunction;
    f->text = ((StrArgList *)list)->ReadString(0);
    return f;
}
void ShowPropFunction::Print()
{
    DebugLog("%s %s", Name(), text.c_str());
    DebugLog("\n");
}
const char *ShowPropFunction::Name() { return "ShowProp"; }

